from pathlib import Path
import hashlib,json,struct
from plan_resource_contracts import pe_info
root=Path(r'D:\MyGitRepo\Grim-Dynasty');out=root/'docs/condition-evaluator'
def get(path):return json.loads(path.read_text())['result']['structuredContent']
collection=get(out/'rea/ConditionCollection-Evaluate.json');factory=get(out/'rea/Condition-Create.json');diff=get(out/'rea-leaves/IsDifficulty-Evaluate.json');hard=get(out/'rea-leaves/IsHardcore-Evaluate.json');wait=get(out/'rea-leaves/WaitForCompletion-Evaluate.json');ctor=get(out/'rea-leaves/ConditionCollection-Ctor.json')
asm=get(out/'rea-leaves/IsDifficulty-Evaluate-assembly.json')['raw_result']['value']
wait_asm=get(out/'rea-leaves/WaitForCompletion-Evaluate-assembly.json')['raw_result']['value']
assert '+ 0x28' in collection['raw_result']['value'] and '0x11' in collection['raw_result']['value']
for text in ['SETL AL','SETLE AL','SETZ AL','SETGE AL','SETG AL','SETNZ AL','CMP dword ptr [RBX + 0x20], EAX','CMOVNZ EAX, dword ptr [RBX + 0x24]']:assert text in asm,text
assert 'XOR AL, AL' in wait_asm and 'RET' in wait_asm
for va in ['180796c90','180796cf0','180797198']:assert va in factory['raw_result']['value']
b,image,offset,exports,ranges=pe_info('x64/Game.dll');loc=json.loads(Path('condition-vtable-locations.json').read_text())
for row in loc:
 if row['class'] not in ['IsDifficulty','IsHardcore','WaitForCompletion']:continue
 va=int(row['vtable'],16);ptr=struct.unpack_from('<Q',b,offset(va-image)+0x28)[0];assert hex(ptr)==row['evaluate_address']
source_sha=hashlib.sha256(b).hexdigest();assert source_sha==diff['subject']['digest']['sha256']==collection['subject']['digest']['sha256']
event=json.loads((root/'docs/resource-contracts/Game-function-evidence-bounded-v2.json').read_text());event=next(x for x in event if 'Quest2Event' in x['label'])
report={'kind':'static-native evidence plus official format data; no original runtime execution','source_sha256':source_sha,'native_evidence':[{'role':role,'evidence_id':v['evidence_id'],'operation':v['operation'],'procedure':v['parameters']['procedure']} for role,v in [('collection',collection),('factory',factory),('difficulty',diff),('hardcore',hard),('wait_shared_false_leaf',wait),('collection_shared_ctor',ctor)]],'vtable_mapping':loc,'difficulty_assembly':asm,'wait_assembly':wait_asm,'difficulty_rule':{'left_operand':'stored threshold [this+0x20] reinterpreted int32','right_operand':'GameInfo difficulty, replaced by [this+0x24] when not 0xffffffff','selectors':{'0':'stored < observed (signed)','1':'stored <= observed (signed)','2':'stored == observed','3':'stored >= observed (signed)','4':'stored > observed (signed)','5':'stored != observed'},'getter_order':'GetGameInfo/GetDifficulty called before override selection','invalid_native_selector':'native returns false; restored API reports Unsupported outside covered enum domain'},'hardcore_rule':'byte equality between main-player offset0x4bd5 and stored byte this+0x20; comparison selector unused; main player is not supplied Entity','collection_rule':{'operation0':'AND; false short-circuit; empty true','operation1':'OR; true short-circuit; empty false','flag':'skip type17 before virtual Evaluate at vtable+0x28','invalid_native_operator':'native false; restored API reports Unsupported outside covered domain'},'aliases':'Wait false leaf and vector-only ctor are linker-folded with many unrelated export names; role established by factory/vtable and call slot, not displayed decompiler name','empty_serialized_definition':'Quest2Event::Read allocates native condition container only when count>0; ctor only zeros vector, not operator field. No assumption that serialized null operator means AND. Adapter returns Unsupported until caller gate semantics are restored.','event_read_evidence':{'source':'docs/resource-contracts/Game-function-evidence-bounded-v2.json','start':event['start'],'end':event['end']},'test_evidence_levels':{'unit_truth_vectors':'fixed expectations from static branches; no Python behavioral oracle','catalog':'official serialized parameters supplied to own evaluator with local simulated inputs; not original game state or behavior observation','original_dynamic_run':'not performed'}}
with (out/'evidence-summary.json').open('x',encoding='utf8') as f:json.dump(report,f,ensure_ascii=False,indent=2)
print(json.dumps({'source_sha256':source_sha,'actual_rea_functions':len(report['native_evidence']),'signed_order_confirmed':True,'skip_flag_confirmed':True},indent=2))
